#!/usr/bin/env bun

// The catalog pin (src/runtime-catalog.generated.ts) is regenerated by
// scripts/bundle-runtime.mjs and ships empty until an operator has run it
// against the production bucket. It can also fall behind a fresh publish.
//
// Neither state may weaken anything. The pin exists to make one shared-cache
// key safe, not to authorise the catalog: R2 is the tier no binding in this
// Worker can write, so a catalog read from it is trusted whether or not the
// pin agrees. So an absent or stale pin must cost the colo cache and nothing
// else — never an outage, and never an unverified read.
//
// This is the failure mode worth testing precisely because it is the quiet
// one: a pin that silently disabled verification instead of caching would
// look identical from the outside.

import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { mock } from 'bun:test';

const WORKER_SRC = new URL('../../packages/worker/src/', import.meta.url);

const enc = (text) => new TextEncoder().encode(text);
const sha = (bytes) => createHash('sha256').update(bytes).digest('hex');

const catalogText = JSON.stringify({
  version: 1,
  runtimes: {
    python: {
      default: '1.0',
      versions: {
        '1.0': { manifest: 'manifests/python-1.0.json', size_bytes: 1, license: 'MIT' },
      },
    },
  },
});
const honestCatalog = enc(catalogText);

const attackerCatalog = enc(JSON.stringify({
  version: 1,
  runtimes: {
    evil: { default: '1.0', versions: { '1.0': { manifest: 'manifests/evil.json', size_bytes: 1, license: 'MIT' } } },
  },
}));

// Ship state: not pinned yet.
mock.module(new URL('runtime-catalog.generated.ts', WORKER_SRC).pathname, () => ({
  RUNTIME_CATALOG_SHA256: '',
}));

const { fetchCatalog } = await import(new URL('runtime/runtime-catalog.ts', WORKER_SRC).pathname);

const store = new Map();
globalThis.caches = {
  default: {
    async match(req) {
      const hit = store.get(req.url);
      return hit ? hit.clone() : undefined;
    },
    async put(req, res) {
      store.set(req.url, res.clone());
    },
  },
};

const env = {
  NIMBUS_RUNTIME_CACHE: {
    async get(key) {
      if (key !== 'catalog/v1.json') return null;
      return {
        async arrayBuffer() {
          return honestCatalog.buffer.slice(honestCatalog.byteOffset, honestCatalog.byteOffset + honestCatalog.byteLength);
        },
        async text() {
          return catalogText;
        },
      };
    },
  },
};

// Plant the attacker's catalog at every address an unpinned read could
// plausibly consult: the digest of the honest bytes (the key a correct pin
// would produce) and the digest of the attacker's own bytes.
for (const ns of ['https://nimbus-runtime-cache-v2.invalid', 'https://nimbus-runtime-cache.invalid']) {
  for (const digest of [sha(honestCatalog), sha(attackerCatalog)]) {
    store.set(`${ns}/catalog/${digest}`, new Response(attackerCatalog));
    store.set(`${ns}/catalog/v1.json`, new Response(attackerCatalog));
  }
}
/** Key → bytes, so a write that overwrites a planted key is still visible.
 *  Comparing key sets alone would not see it. */
async function snapshot() {
  const out = [];
  for (const [url, res] of store) out.push([url, sha(new Uint8Array(await res.clone().arrayBuffer()))]);
  return out.sort();
}
const planted = await snapshot();

const warnings = [];
const realWarn = console.warn;
console.warn = (...args) => { warnings.push(args.join(' ')); };

let catalog;
try {
  catalog = await fetchCatalog(env);
  // A stale pin must not become an outage on the next fetch either.
  await fetchCatalog(env);
} finally {
  console.warn = realWarn;
}

// 1. Unverifiable means read from R2, not read from the shared cache.
assert.deepEqual(
  Object.keys(catalog.runtimes),
  ['python'],
  'an unpinned catalog was served from L2 — the pin disabled verification instead of caching',
);

// 2. And not written to it either: caching bytes under a key nothing
//    vouches for is what made the old keyspace poisonable.
assert.deepEqual(
  await snapshot(),
  planted,
  'an unverifiable catalog was written into the shared cache',
);

// 3. Silence would make a disabled cache indistinguishable from a working
//    one. Once per isolate, not once per fetch.
assert.equal(warnings.length, 1, `expected exactly one warning across two fetches, got ${warnings.length}`);
assert.match(warnings[0], /RUNTIME_CATALOG_SHA256/, 'the warning does not name the constant to regenerate');
assert.match(warnings[0], /--pin-catalog/, 'the warning does not say how to fix it');

console.log('runtime-catalog-unpinned: ok');
